(()=>{'use strict';
const start=async()=>{const overlay=document.createElement('section');overlay.id='ma5-initializing';overlay.setAttribute('role','alert');overlay.style.cssText='position:fixed;inset:0;z-index:100001;background:#fff8ed;padding:30px;overflow:auto;color:#4b3620';overlay.textContent='Inicializando proteção A5 e conferindo recuperação pendente…';document.body.append(overlay);
 try{await MA5.boot();const failures=[];const onError=e=>failures.push(e.message);window.addEventListener('error',onError);
  for(const old of [...document.querySelectorAll('script[data-ma5-app]')]){const script=document.createElement('script');for(const attr of old.attributes)if(!['type','data-ma5-app'].includes(attr.name))script.setAttribute(attr.name,attr.value);script.textContent=old.textContent;old.replaceWith(script);if(failures.length)throw Error('Falha de inicialização: '+failures.join('; '));}
  window.removeEventListener('error',onError);MA5.bindUI();MA5.appReady=true;overlay.remove();
 }catch(e){MA5.guardFailure=e.message;overlay.replaceChildren();const h=document.createElement('h2');h.textContent='Proteção/recuperação pendente: gravações bloqueadas';const p=document.createElement('p');p.textContent=e.message+'. Feche outras abas e recarregue. Nenhum dado será substituído para contornar este bloqueio.';const b=document.createElement('button');b.type='button';b.textContent='Baixar cópia FORENSE das chaves DEV atuais';b.onclick=()=>{const body={format:'manfrin-arnez-forensic-readonly',version:1,createdAt:new Date().toISOString(),warning:'Não é backup completo nem snapshot de estado anterior; contém os bytes atualmente acessíveis. Não restaurar diretamente.',state:MA5.localEntries()};MA5.download('Manfrin-Arnez-FORENSE-BLOQUEADO-A5.json',JSON.stringify(body,null,2));};overlay.append(h,p,b);const retry=document.createElement('button');retry.type='button';retry.textContent='Recarregar para conferir recuperação';retry.onclick=()=>location.reload();overlay.append(retry);}
};
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',start,{once:true});else start();
})();
